begin;
select no_plan();
insert into cooksmith.app_user_roles(user_id,role) values('10000000-0000-4000-8000-000000000001','admin') on conflict do nothing;
update cooksmith.recipe_intelligence_settings set enqueue_enabled=true,emergency_stop=false,backfill_paused=false,ai_enabled=false where singleton;
insert into cooksmith.household_recipes(id,household_id,name,ingredients,source_url,measurement_system) values('a1010000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','Structure household','1 garlic, diced','https://example.invalid/household','au');
insert into cooksmith.imported_recipes(id,visibility,owner_id,name,source_url) values('a1010000-0000-4000-8000-000000000001','public','10000000-0000-4000-8000-000000000001','Structure shared','https://example.invalid/shared'),('a1010000-0000-4000-8000-000000000002','private','10000000-0000-4000-8000-000000000001','Structure private','https://example.invalid/private');
select is((select count(*)::integer from cooksmith.recipe_content_versions where coalesce(recipe_id,imported_recipe_id)='a1010000-0000-4000-8000-000000000001'),2,'Same recipe ID has separate household and public source versions');
select is((select count(*)::integer from cooksmith.recipe_content_versions where imported_recipe_id='a1010000-0000-4000-8000-000000000002'),0,'Owner-only import is not published to shared enrichment');
select is((select source_snapshot->'recipe'->>'measurementSystem' from cooksmith.recipe_content_versions where recipe_id='a1010000-0000-4000-8000-000000000001'),'au','Version snapshot retains measurement convention');
insert into cooksmith.recipe_ingredients(recipe_id,ingredient_name,quantity_text,original_line_text,parser_version,position,ingredient_structure) values('a1010000-0000-4000-8000-000000000001','garlic','1','1 garlic, diced','recipe-content-v2',1,'{"schemaVersion":"ingredient-structure-v1","rulesVersion":"ingredient-structure-rules-v1","originalText":"1 garlic, diced","substitutions":[],"noteReferences":[]}');
select throws_ok($$update cooksmith.recipe_ingredients set ingredient_structure='{}' where recipe_id='a1010000-0000-4000-8000-000000000001'$$,'23514',null,'Incomplete structure cannot pass nullable CHECK logic');
select throws_ok($$update cooksmith.recipe_ingredients set ingredient_structure=jsonb_set(ingredient_structure,'{originalText}','"different source"') where recipe_id='a1010000-0000-4000-8000-000000000001'$$,'23514',null,'Structured original must match retained source');
select is((select source_snapshot->'ingredients'->0->>'parserVersion' from cooksmith.recipe_content_versions where recipe_id='a1010000-0000-4000-8000-000000000001' order by created_at desc,id desc limit 1),'recipe-content-v2','Latest snapshot includes the saved parser version');
select ok((select source_snapshot->'ingredients'->0 ? 'structure' from cooksmith.recipe_content_versions where recipe_id='a1010000-0000-4000-8000-000000000001' order by created_at desc,id desc limit 1),'Latest snapshot carries the shared structure');
-- Simulate a valid legacy active result before the operator opts into new rules.
delete from cooksmith.recipe_enrichment_jobs where coalesce(recipe_id,imported_recipe_id)='a1010000-0000-4000-8000-000000000001';
insert into cooksmith.recipe_enrichment_jobs(id,source_kind,recipe_id,household_id,recipe_version_id,state,rules_version,model_key,leased_until)
select 'a1010000-0000-4000-8000-000000000003','household',recipe_id,household_id,id,'processing','cooksmith-rules-v3','provider-assisted-v2',now()+interval '2 minutes' from cooksmith.recipe_content_versions where recipe_id='a1010000-0000-4000-8000-000000000001' order by created_at desc,id desc limit 1;
select lives_ok($$select cooksmith.activate_recipe_enrichment('a1010000-0000-4000-8000-000000000003','fake','fake','{"preparationOpportunities":[{"opportunityId":"old"}]}','high')$$,'Legacy worker remains compatible before a replacement is active');
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000003',true);
select throws_ok($$select cooksmith.recipe_enrichment_backfill_command('reprocess_structure',1)$$,'42501',null,'Non-admin cannot reprocess recipes');
select throws_ok($$select cooksmith.recipe_enrichment_backfill_status()$$,'42501',null,'Preview remains admin protected');
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000001',true);
select ok((cooksmith.recipe_enrichment_backfill_status()->'structurePreview'->>'household')::integer>=1,'Preview reports eligible household recipes');
select ok((cooksmith.recipe_enrichment_backfill_status()->'structurePreview'->>'sharedPlatform')::integer>=1,'Preview reports eligible shared recipes separately');
select ok((cooksmith.recipe_enrichment_backfill_command('reprocess_structure',1)->>'queued')::integer<=1,'Operator batch obeys requested bound');
select cooksmith.recipe_enrichment_backfill_command('reprocess_structure',100);
select is((cooksmith.recipe_enrichment_backfill_command('reprocess_structure',100)->>'queued')::integer,0,'Repeated completed enqueue is idempotent');
select cooksmith.recipe_enrichment_backfill_command('pause',100);
select throws_ok($$select cooksmith.recipe_enrichment_backfill_command('reprocess_structure',1)$$,'55000',null,'Paused reprocessing fails closed');
select cooksmith.recipe_enrichment_backfill_command('resume',100);
reset role;
select ok((select is_active from cooksmith.recipe_enrichments where job_id='a1010000-0000-4000-8000-000000000003'),'Queueing keeps the previous valid result active');
select is((select ingredients from cooksmith.household_recipes where id='a1010000-0000-4000-8000-000000000001'),'1 garlic, diced','Reprocessing preserves the approved recipe');
update cooksmith.recipe_enrichment_jobs set state='processing',leased_until=now()+interval '2 minutes' where recipe_id='a1010000-0000-4000-8000-000000000001' and rules_version='cooksmith-rules-v4';
select throws_ok($$select cooksmith.activate_recipe_enrichment((select id from cooksmith.recipe_enrichment_jobs where recipe_id='a1010000-0000-4000-8000-000000000001' and rules_version='cooksmith-rules-v4'),'fake','fake','{"rulesVersion":"cooksmith-rules-v3","preparationOpportunities":[{"opportunityId":"old-worker"}]}','high')$$,'P0001','stale_rules','Old deployed worker output cannot be labelled with new job rules');
select lives_ok($$select cooksmith.activate_recipe_enrichment((select id from cooksmith.recipe_enrichment_jobs where recipe_id='a1010000-0000-4000-8000-000000000001' and rules_version='cooksmith-rules-v4'),'fake','fake','{"preparationOpportunities":[{"opportunityId":"new"}]}','high')$$,'New rules activate a validated replacement through the existing authority');
select ok(not (select is_active from cooksmith.recipe_enrichments where job_id='a1010000-0000-4000-8000-000000000003'),'Previous immutable result is retained but inactive');
update cooksmith.recipe_enrichment_jobs set state='processing',leased_until=now()+interval '2 minutes' where id='a1010000-0000-4000-8000-000000000003';
select throws_ok($$select cooksmith.activate_recipe_enrichment('a1010000-0000-4000-8000-000000000003','fake','fake','{"preparationOpportunities":[{"opportunityId":"late"}]}','high')$$,'P0001','stale_rules','An old worker cannot supersede current rules');
select is((select count(*)::integer from cooksmith.recipe_enrichments where recipe_id='a1010000-0000-4000-8000-000000000001' and is_active),1,'Exactly one active result remains');
select ok(not has_function_privilege('anon','cooksmith.refresh_shopping_ingredient_structure(uuid,jsonb)','EXECUTE'),'Anonymous refresh denied');
select ok(not has_function_privilege('authenticated','cooksmith.activate_recipe_enrichment(uuid,text,text,jsonb,text)','EXECUTE'),'Household clients cannot activate intelligence');
select * from finish();
rollback;
